<template>
  <!-- XMCL HomeGrid card vocabulary, backed by Luna operations. -->
  <section class="xmcl-home-grid">
    <article class="xmcl-card xmcl-card-mods" @click="emit('navigate','mods')"><header><q-icon name="extension"/><strong>模组</strong><q-btn flat round dense icon="open_in_new" @click.stop="emit('navigate','mods')"/></header><div class="xmcl-card-number">{{ counts.mods }}</div><small>已安装资源</small><div class="xmcl-card-list"><div v-for="item in resources.mods.slice(0,4)" :key="item.fileName"><span>{{ item.name||item.fileName }}</span><q-icon :name="item.enabled?'check':'visibility_off'" size="16px"/></div><div v-if="!resources.mods.length" class="xmcl-empty">没有安装模组</div></div></article>
    <article class="xmcl-card xmcl-card-resource" @click="emit('navigate','resourcepacks')"><header><q-icon name="palette"/><strong>资源包</strong><q-btn flat round dense icon="open_in_new"/></header><div class="xmcl-card-number">{{ counts.resourcepacks }}</div><small>已安装资源</small><div class="xmcl-card-list"><div v-for="item in resources.resourcepacks.slice(0,4)" :key="item.fileName"><span>{{ item.name||item.fileName }}</span><q-icon :name="item.enabled?'check':'visibility_off'" size="16px"/></div><div v-if="!resources.resourcepacks.length" class="xmcl-empty">没有安装资源包</div></div></article>
    <article class="xmcl-card xmcl-card-worlds" @click="emit('navigate','save')"><header><q-icon name="public"/><strong>世界</strong><q-btn flat round dense icon="open_in_new"/></header><div class="xmcl-card-number">{{ worlds.length }}</div><small>本地存档</small><div class="xmcl-card-list"><div v-for="world in worlds.slice(0,4)" :key="world.folder"><span>{{ world.name||world.folder }}</span><q-icon name="chevron_right" size="16px"/></div><div v-if="!worlds.length" class="xmcl-empty">没有发现世界</div></div></article>
    <article class="xmcl-card xmcl-card-screenshots" @click="emit('extras')"><header><q-icon name="photo_library"/><strong>截图</strong><q-btn flat round dense icon="open_in_new"/></header><div class="xmcl-screenshot-grid"><img v-for="shot in screenshots.slice(0,6)" :key="shot.name" :src="shot.dataUrl||shot.url" :alt="shot.name"/><div v-if="!screenshots.length" class="xmcl-empty">没有截图</div></div></article>
  </section>
</template>
<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
const props=defineProps<{instance:string;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();
const emit=defineEmits<{navigate:[page:string];extras:[]}>();
const resources=ref<Record<string,any[]>>({mods:[],resourcepacks:[]}),worlds=ref<any[]>([]),screenshots=ref<any[]>([]);const counts={mods:0,resourcepacks:0};
async function load(){try{const [mods,packs,w,s]=await Promise.all([props.execute('resource.list',{instance:props.instance,kind:'mods'}),props.execute('resource.list',{instance:props.instance,kind:'resourcepacks'}),props.execute('instance.world.list',{instance:props.instance}),props.execute('instance.screenshot.list',{instance:props.instance})]);resources.value={mods:Array.isArray(mods)?mods:[],resourcepacks:Array.isArray(packs)?packs:[]};counts.mods=resources.value.mods.length;counts.resourcepacks=resources.value.resourcepacks.length;worlds.value=Array.isArray(w)?w:[];screenshots.value=Array.isArray(s)?s:[];}catch{/* The detailed page displays the operation error. */}}
watch(()=>props.instance,load);onMounted(load);
</script>
